package com.aliplankstu.qingping;
import android.accessibilityservice.*;import android.view.accessibility.*;import android.view.*;import java.util.*;
public class AdGuardService extends AccessibilityService {long last=0;public void onAccessibilityEvent(AccessibilityEvent e){if(e==null||System.currentTimeMillis()-last<1200)return;AccessibilityNodeInfo root=getRootInActiveWindow();if(root==null)return;ArrayList<AccessibilityNodeInfo> nodes=new ArrayList<>();collect(root,nodes,0);for(AccessibilityNodeInfo n:nodes){CharSequence t=n.getText(),d=n.getContentDescription();String s=((t==null?"":t.toString())+" "+(d==null?"":d.toString())).toLowerCase(Locale.ROOT);if((s.contains("跳过")||s.contains("skip")||s.contains("关闭")||s.contains("close")||s.equals("×")||s.equals("x"))&&n.isClickable()){if(n.performAction(AccessibilityNodeInfo.ACTION_CLICK)){getSharedPreferences("stats",0).edit().putInt("hits",getSharedPreferences("stats",0).getInt("hits",0)+1).apply();last=System.currentTimeMillis();break;}}}}void collect(AccessibilityNodeInfo n,List<AccessibilityNodeInfo> out,int depth){if(n==null||depth>12)return;out.add(n);for(int i=0;i<n.getChildCount();i++)collect(n.getChild(i),out,depth+1);}public void onInterrupt(){}}